1	/**
2	 * Screen 04 milestone M4 (round 8, qa/match/04/NOTES.md) — sub-switches of `?match04=1`, each `&m04…=1`, default off:
3	 *  m04ring  — the gold washer opening and the gold-ring tunnel as REAL modeled geometry (lathe profiles sized from the
4	 *             approved picture's mouth ring r 3.58 → 4.11 and the painted stacked ring bands), shaded as polished gold
5	 *             (warm glow down the tunnel, pink / violet / cyan water reflections on the lower walls, glints, a row of
6	 *             amber bulbs on the opening and on every ring lip). In the approved view these surfaces show the approved
7	 *             pixels (camera projection, unchanged); they fade to their own crisp 3D gold as the camera leaves that view.
8	 *  m04foam  — puffy 3D foam banks along both water edges (the painted white-lilac foam clusters), hidden in the approved
9	 *             view (the painting carries them there), shown once the camera has left it.
10	 *  m04bub   — iridescent soap bubbles floating in the tunnel air (camera-facing bubble discs), same visibility rule.
11	 *  m04arrow — the five glowing blue chevron arrows drawn crisp on the water (distance-field shape at the painted
12	 *             spacing) instead of the magnified painted arrow tile.
13	 *  m04wave  — the painted swirl water without the obvious repeat (two offset samples of the swirl tile blended by a
14	 *             slow world-anchored noise) and flowing down the slide.
15	 * Without `?match04=1` nothing here runs; without the sub-switches nothing here is built.
16	 */
17	import * as THREE from 'three';
18	import { PROJ05_INVERSE } from '../vfx/waterRibbon';
19	
20	const QS = new URLSearchParams(location.search);
21	const on = (k: string) => QS.get(k) === '1';
22	export const M04 = {
23	  ring: on('m04ring'),
24	  foam: on('m04foam'),
25	  bub: on('m04bub'),
26	  arrow: on('m04arrow'),
27	  wave: on('m04wave'),
28	  num: (k: string, d: number) => (QS.has(k) ? Number(QS.get(k)) : d),
29	};
30	
31	export interface M04Ctx {
32	  group: THREE.Group;
33	  shared: Record<string, THREE.IUniform>;
34	  proj: THREE.PerspectiveCamera;
35	  /** tube axis in group-local coordinates (x lateral, y up from the slide, z = -down the slide) */
36	  cx: number; cy: number; z0: number; len: number; r: number; outerR: number;
37	  hideOld: (names: string[]) => void;
38	}
39	
40	const VERT = /* glsl */ `
41	uniform mat4 uProjVP;
42	attribute vec2 aK;
43	varying vec4 vProj;
44	varying vec3 vW;
45	varying vec3 vN;
46	varying vec2 vK;
47	void main() {
48	  vec4 wp = modelMatrix * vec4(position, 1.0);
49	  vProj = uProjVP * wp;
50	  vW = wp.xyz;
51	  vK = aK;
52	  vN = normalize(mat3(modelMatrix) * normal);
53	  gl_Position = projectionMatrix * viewMatrix * wp;
54	}`;
55	
56	// polished gold: everything in DISPLAY colours (measured on the approved picture), then pjInverse like the plate
57	const GOLD_FRAG = /* glsl */ `
58	uniform sampler2D uPlate;
59	uniform vec4 uPjPost;
60	uniform vec2 uPjRes;
61	uniform float uAway;
62	uniform vec3 uAxO;
63	uniform vec3 uAxD;
64	uniform vec3 uAxU;
65	uniform vec3 uAxR;
66	uniform float uNB;
67	uniform float uP;
68	uniform float uLipBulb;
69	uniform float uBulbR;
70	varying vec4 vProj;
71	varying vec3 vW;
72	varying vec3 vN;
73	varying vec2 vK;            // x: part (0 band, 1 lip, 2 groove, 3 opening face, 4 end glow), y: ring index
74	${PROJ05_INVERSE}
75	float h21(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
76	void main() {
77	  vec3 V = normalize(cameraPosition - vW);
78	  vec3 n = normalize(vN);
79	  if (dot(n, V) < 0.0) n = -n;
80	  vec3 q = vW - uAxO;
81	  float al = dot(q, uAxD);
82	  vec3 qr = q - uAxD * al;
83	  float rr = length(qr);
84	  float ang = atan(dot(qr, uAxR), dot(qr, uAxU));         // 0 = tunnel top
85	  vec3 R = reflect(-V, n);
86	  float fw = dot(R, uAxD);                                 // reflection toward the warm glow down the tunnel
87	  float dn = -dot(R, uAxU);                                // reflection toward the water below
88	  float part = vK.x;
89	  vec3 col;
90	  if (part > 3.5) {
91	    // the far glow of the tunnel (painted vanishing point): warm white core -> orange
92	    float rad = clamp(rr / 3.6, 0.0, 1.0);
93	    col = mix(vec3(1.0, 0.97, 0.86), vec3(1.0, 0.70, 0.38), smoothstep(0.0, 1.0, rad));
94	  } else {
95	    // art-directed polished gold in the approved picture's display colours: shadow (157,67,65) / mid (210,116,71) /
96	    // lit (251,190,106) / hot glint (254,250,220); saturated orange, never the grey-tan of a physical reflection
97	    bool mouth = vK.y < -0.5;
98	    float u = fract(al / uP);                                // position inside one ring period (0 groove .. 1 lip)
99	    float band = smoothstep(0.05, 0.95, u);
100	    float streak = 0.5 + 0.5 * sin(ang * 3.0 + 1.7 + 0.8 * sin(ang * 7.0));
101	    float dc = distance(cameraPosition, vW);
102	    float sp = pow(max(dot(R, normalize(uAxD * 0.75 + uAxU * 0.55)), 0.0), 18.0) + 0.7 * pow(max(dot(R, normalize(uAxD * 0.8 - uAxR * 0.5)), 0.0), 22.0);
103	    if (mouth) {
104	      // the washer opening: bright polished gold face, glowing lips
105	      col = mix(vec3(0.90, 0.52, 0.18), vec3(1.0, 0.74, 0.36), 0.5 + 0.5 * sin(ang * 2.0 + 0.6));
106	      col = mix(col, vec3(1.0, 0.80, 0.42), 0.35 * smoothstep(0.3, 0.95, dot(n, V)) * streak);
107	      if (part > 0.5 && part < 1.5) col = mix(col, vec3(1.0, 0.88, 0.58), smoothstep(0.55, 0.95, dot(n, V)) * (0.4 + 0.5 * streak));
108	      if (part > 1.5 && part < 2.5) col = vec3(0.55, 0.22, 0.10);
109	    } else {
110	      float a = clamp(0.30 + 0.50 * band + 0.30 * (streak - 0.5), 0.0, 1.0);
111	      col = mix(vec3(0.58, 0.24, 0.13), vec3(0.88, 0.47, 0.19), a);
112	      col = mix(col, vec3(1.0, 0.72, 0.34), 0.5 * smoothstep(0.55, 0.98, fw) * smoothstep(0.35, 1.0, band));
113	      // the tunnel brightens toward its glowing far end
114	      col = mix(col, vec3(1.0, 0.74, 0.40), 0.45 * smoothstep(14.0, 44.0, dc));
115	      // lips: a thin hot line where the bead faces the viewer, orange-gold elsewhere; grooves: dark copper
116	      if (part > 0.5 && part < 1.5) col = mix(col, vec3(1.0, 0.90, 0.60), smoothstep(0.35, 0.9, dot(n, V)) * (0.5 + 0.4 * streak));
117	      if (part > 1.5 && part < 2.5) col = mix(col, vec3(0.33, 0.10, 0.06), 0.8);
118	    }
119	    // pink / violet / cyan reflections of the swirl water, strongest on the lower walls
120	    float hue = 0.5 + 0.5 * sin(ang * 2.3 + al * 0.45 + h21(vec2(floor(al / 2.0), 3.0)) * 6.0);
121	    vec3 wc = mix(vec3(0.96, 0.40, 0.72), vec3(0.52, 0.52, 1.0), hue);
122	    float wr = smoothstep(-0.1, 0.7, dn) * (0.35 + 0.65 * smoothstep(-0.3, 0.7, -cos(ang)));
123	    col = mix(col, wc, 0.38 * wr * (mouth ? 0.5 : 1.0));
124	    col += vec3(1.0, 0.82, 0.48) * 0.30 * sp;
125	    // amber bulbs on the washer opening's face (and, if asked, on the ring lips)
126	    if ((part > 2.5 && part < 3.5) || (uLipBulb > 0.5 && part > 0.5 && part < 1.5 && !mouth)) {
127	      float nb = part > 2.5 ? uNB : uNB * 0.75;
128	      float cell = fract(ang / 6.2831853 * nb + 0.5 * mod(vK.y, 2.0)) - 0.5;
129	      float arc = cell * 6.2831853 * rr / nb;               // world units along the ring
130	      float rad = part > 2.5 ? abs(rr - uBulbR) : 0.0;
131	      float d = length(vec2(arc, rad));
132	      float bs = part > 2.5 ? 0.07 : 0.045;
133	      col += vec3(1.0, 0.60, 0.20) * 0.45 * smoothstep(bs * 3.0, 0.0, d);
134	      col = mix(col, vec3(1.0, 0.96, 0.82), smoothstep(bs, bs * 0.4, d));
135	    }
136	    // star glints scattered on the polished gold (painted white sparkles)
137	    vec2 gc = vec2(ang / 6.2831853 * 34.0, al * 1.3);
138	    vec2 gi = floor(gc), gf = fract(gc) - 0.5;
139	    float gh = h21(gi + vK.y * 7.0);
140	    if (gh > 0.9) {
141	      vec2 o = (vec2(h21(gi + 1.3), h21(gi + 2.7)) - 0.5) * 0.6;
142	      vec2 p = (gf - o) * vec2(1.0, 0.7);
143	      float g = smoothstep(0.09, 0.0, length(p)) + 0.5 * smoothstep(0.02, 0.0, abs(p.x)) * smoothstep(0.3, 0.0, abs(p.y)) + 0.5 * smoothstep(0.02, 0.0, abs(p.y)) * smoothstep(0.3, 0.0, abs(p.x));
144	      col += vec3(1.0, 0.95, 0.82) * g * 0.75;
145	    }
146	  }
147	  col = clamp(col, 0.0, 1.0);
148	  // the approved view shows the approved pixels (the projector IS this camera there)
149	  if (uAway < 0.999 && vProj.w > 0.0) {
150	    vec2 uv = vProj.xy / vProj.w * 0.5 + 0.5;
151	    if (uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0) col = mix(texture2D(uPlate, uv).rgb, col, uAway);
152	  }
153	  gl_FragColor = vec4(pjInverse(col), 1.0);
154	}`;
155	
156	/** world-space bubble discs + foam puffs share one tiny shader each (camera-facing sprites in an InstancedMesh) */
157	const SPRITE_VERT = /* glsl */ `
158	attribute vec4 aB;          // xyz world centre, w radius
159	attribute float aS;         // seed
160	varying vec2 vUv;
161	varying float vS;
162	void main() {
163	  vUv = uv * 2.0 - 1.0;
164	  vS = aS;
165	  vec4 mv = viewMatrix * vec4(aB.xyz, 1.0);
166	  mv.xy += position.xy * aB.w * 2.0;
167	  gl_Position = projectionMatrix * mv;
168	}`;
169	const BUB_FRAG = /* glsl */ `
170	uniform vec4 uPjPost;
171	uniform vec2 uPjRes;
172	uniform float uAlpha;
173	varying vec2 vUv;
174	varying float vS;
175	${PROJ05_INVERSE}
176	void main() {
177	  float r = length(vUv);
178	  if (r > 1.0) discard;
179	  // soap bubble: clear centre, iridescent rim (pink -> violet -> cyan around it), white window highlight
180	  float rim = smoothstep(0.55, 0.97, r) * (1.0 - smoothstep(0.97, 1.0, r));
181	  float a = atan(vUv.y, vUv.x) + vS * 6.0;
182	  vec3 iri = 0.5 + 0.5 * cos(vec3(0.0, 2.1, 4.2) + a * 1.0 + r * 3.0);
183	  iri = mix(vec3(0.95, 0.55, 0.95), iri, 0.55);
184	  vec3 col = mix(vec3(0.86, 0.80, 1.0), iri, rim);
185	  float hl = smoothstep(0.24, 0.05, length(vUv - vec2(-0.38, 0.42)));
186	  float alpha = 0.10 + 0.70 * rim + 0.85 * hl;
187	  col = mix(col, vec3(1.0), hl);
188	  gl_FragColor = vec4(pjInverse(col), clamp(alpha, 0.0, 1.0) * uAlpha);
189	}`;
190	const FOAM_FRAG = /* glsl */ `
191	uniform vec4 uPjPost;
192	uniform vec2 uPjRes;
193	uniform float uAlpha;
194	varying vec2 vUv;
195	varying float vS;
196	${PROJ05_INVERSE}
197	void main() {
198	  float r = length(vUv);
199	  if (r > 1.0) discard;
200	  // a foam bubble ball as painted: lilac-white sphere shading, bright upper-left, violet-blue lower rim, soft edge
201	  vec3 nrm = vec3(vUv, sqrt(max(0.0, 1.0 - r * r)));
202	  float l = clamp(dot(nrm, normalize(vec3(-0.45, 0.6, 0.65))), 0.0, 1.0);
203	  vec3 col = mix(vec3(0.70, 0.68, 0.95), vec3(0.98, 0.96, 1.0), l);
204	  col = mix(col, vec3(0.98, 0.78, 0.95), 0.25 * smoothstep(0.6, 1.0, r) * (0.5 + 0.5 * sin(vS * 9.0)));
205	  col += vec3(1.0) * 0.5 * smoothstep(0.22, 0.0, length(vUv - vec2(-0.35, 0.4)));
206	  float alpha = 1.0 - smoothstep(0.88, 1.0, r);
207	  gl_FragColor = vec4(pjInverse(clamp(col, 0.0, 1.0)), alpha * uAlpha);
208	}`;
209	
210	function lathe(prof: { r: number; a: number; part: number }[], segs: number, ringIdx: (i: number) => number) {
211	  const pts = prof.map((p) => new THREE.Vector2(p.r, p.a));
212	  const g = new THREE.LatheGeometry(pts, segs);
213	  const n = g.attributes.position.count;
214	  const k = new Float32Array(n * 2);
215	  // LatheGeometry: vertex index = seg * pts.length + j
216	  for (let i = 0; i < n; i++) { const j = i % pts.length; k[i * 2] = prof[j].part; k[i * 2 + 1] = ringIdx(j); }
217	  g.setAttribute('aK', new THREE.Float32BufferAttribute(k, 2));
218	  g.deleteAttribute('uv');
219	  return g;
220	}
221	
222	export function addM04(ctx: M04Ctx) {
223	  const { group, shared, proj, cx, cy, z0, len, r } = ctx;
224	  const any = M04.ring || M04.foam || M04.bub || M04.arrow || M04.wave;
225	  if (!any) return null;
226	  group.updateMatrixWorld(true);
227	  const Mw = group.matrixWorld;
228	  const toW = (x: number, y: number, z: number) => new THREE.Vector3(x, y, z).applyMatrix4(Mw);
229	  const axO = toW(cx, cy, z0), axD = toW(cx, cy, z0 - 1).sub(axO).normalize();
230	  const axU = toW(cx, cy + 1, z0).sub(axO).normalize(), axR = toW(cx + 1, cy, z0).sub(axO).normalize();
231	  const away = { value: 0 };
232	  const fade = (M04.num('m04fade0', 0.3)), fade1 = M04.num('m04fade1', 2.5);
233	  const out: { update(cam: THREE.Vector3): void } = { update() {} };
234	  const updaters: ((a: number) => void)[] = [];
235	
236	  if (M04.ring) {
237	    const gm = new THREE.ShaderMaterial({
238	      vertexShader: VERT, fragmentShader: GOLD_FRAG, side: THREE.DoubleSide, fog: false,
239	      uniforms: { uPlate: shared.uPlate, uPjPost: shared.uPjPost, uPjRes: shared.uPjRes, uProjVP: shared.uProjVP,
240	        uAway: away, uAxO: { value: axO }, uAxD: { value: axD }, uAxU: { value: axU }, uAxR: { value: axR }, uNB: { value: M04.num('m04nb', 28) },
241	        uP: { value: M04.num('m04ringp', 2.4) }, uLipBulb: { value: M04.num('m04lipbulb', 0) }, uBulbR: { value: (r + ctx.outerR) / 2 } },
242	    });
243	    const P = M04.num('m04ringp', 2.4); // ring period along the tunnel (painted stacked bands)
244	    // corrugated tunnel wall: per period a band that narrows slightly toward the glow (faces the camera like the painted
245	    // stacked bands), a rounded lip bead with bulbs, a dark groove; axial a = distance down the tunnel from the mouth
246	    const prof: { r: number; a: number; part: number }[] = [];
247	    const ringOf: number[] = [];
248	    const nP = Math.ceil(len / P);
249	    for (let k = 0; k < nP; k++) {
250	      const a = k * P;
251	      const pushP = (rr: number, aa: number, part: number) => { prof.push({ r: rr, a: aa, part }); ringOf.push(k); };
252	      pushP(r + 0.14, a + 0.02, 2);
253	      pushP(r + 0.08, a + 0.10, 0);
254	      pushP(r - 0.02, a + P * 0.45, 0);
255	      pushP(r - 0.10, a + P - 0.50, 0);
256	      pushP(r - 0.12, a + P - 0.44, 1);
257	      pushP(r - 0.22, a + P - 0.36, 1);
258	      pushP(r - 0.26, a + P - 0.27, 1);
259	      pushP(r - 0.22, a + P - 0.18, 1);
260	      pushP(r - 0.10, a + P - 0.10, 2);
261	      pushP(r + 0.14, a + P - 0.02, 2);
262	    }
263	    const tun = lathe(prof, 160, (j) => ringOf[j]);
264	    // lathe axis = +y; rotate so y -> -z (down the tunnel), then place at the mouth
265	    tun.rotateX(-Math.PI / 2).translate(cx, cy, z0);
266	    const tm = new THREE.Mesh(tun, gm); tm.name = 'm04_ring_tunnel'; group.add(tm);
267	    // the washer opening: thick polished ring r 3.58 -> 4.11 in front of the wall, rounded lips, bulb row on the face
268	    const R0 = r, R1 = ctx.outerR;
269	    const mp: { r: number; a: number; part: number }[] = [
270	      { r: R0 + 0.02, a: 0.5, part: 1 }, { r: R0 - 0.04, a: 0.2, part: 1 }, { r: R0 - 0.06, a: -0.2, part: 1 },
271	      { r: R0 - 0.02, a: -0.45, part: 1 }, { r: R0 + 0.06, a: -0.58, part: 1 }, { r: R0 + 0.12, a: -0.62, part: 3 },
272	      { r: (R0 + R1) / 2, a: -0.66, part: 3 }, { r: R1 - 0.1, a: -0.62, part: 3 }, { r: R1 - 0.04, a: -0.56, part: 1 },
273	      { r: R1 + 0.01, a: -0.42, part: 1 }, { r: R1 + 0.02, a: -0.1, part: 1 }, { r: R1 + 0.02, a: 0.05, part: 2 },
274	    ];
275	    const mouth = lathe(mp, 192, () => -1);
276	    mouth.rotateX(-Math.PI / 2).translate(cx, cy, z0);
277	    const mm = new THREE.Mesh(mouth, gm); mm.name = 'm04_ring_mouth'; group.add(mm);
278	    // far glow instead of the flat end cap
279	    const cap = new THREE.CircleGeometry(r + 0.2, 64).translate(cx, cy, z0 - len);
280	    const nC = cap.attributes.position.count;
281	    cap.setAttribute('aK', new THREE.Float32BufferAttribute(new Float32Array(nC * 2).map((_, i) => (i % 2 === 0 ? 4 : 0)), 2));
282	    const cm = new THREE.Mesh(cap, gm); cm.name = 'm04_ring_glow'; group.add(cm);
283	    ctx.hideOld(['m04_tube', 'm04_mouth_ring', 'm04_tube_end']);
284	    console.info('[match04] m04ring', { period: P, rings: nP });
285	  }
286	
287	  // sprite clouds (foam puffs, bubbles): world positions computed in the slide-local frame
288	  const sprites = (items: { p: THREE.Vector3; r: number; s: number }[], frag: string, name: string, order: number) => {
289	    const quad = new THREE.PlaneGeometry(1, 1);
290	    const g = new THREE.InstancedBufferGeometry();
291	    g.setIndex(quad.index); g.setAttribute('position', quad.attributes.position); g.setAttribute('uv', quad.attributes.uv);
292	    const aB = new Float32Array(items.length * 4), aS = new Float32Array(items.length);
293	    items.forEach((it, i) => { const w = it.p.clone().applyMatrix4(Mw); aB.set([w.x, w.y, w.z, it.r], i * 4); aS[i] = it.s; });
294	    g.setAttribute('aB', new THREE.InstancedBufferAttribute(aB, 4));
295	    g.setAttribute('aS', new THREE.InstancedBufferAttribute(aS, 1));
296	    g.instanceCount = items.length;
297	    const alpha = { value: 0 };
298	    const m = new THREE.ShaderMaterial({ vertexShader: SPRITE_VERT, fragmentShader: frag, transparent: true, depthWrite: false, fog: false,
299	      uniforms: { uPjPost: shared.uPjPost, uPjRes: shared.uPjRes, uAlpha: alpha } });
300	    const mesh = new THREE.Mesh(g, m);
301	    mesh.name = name; mesh.frustumCulled = false; mesh.renderOrder = order; mesh.visible = false; // invisible during the projector depth bake
302	    group.add(mesh);
303	    updaters.push((a) => { alpha.value = a; mesh.visible = a > 0.01; });
304	  };
305	  let seed = 4321; const rnd = () => ((seed = (seed * 16807) % 2147483647) / 2147483647);
306	  const waterHalf = Math.sqrt(Math.max(0, r * r - cy * cy)); // where the water meets the tunnel wall
307	  if (M04.foam) {
308	    const items: { p: THREE.Vector3; r: number; s: number }[] = [];
309	    // inside the tunnel: irregular foam clusters (0.6–1.6 u long, gaps between) along both water edges, climbing a
310	    // little up the wall — the painted white-lilac bubbly foam, not a continuous rope
311	    for (const side of [-1, 1]) {
312	      let a = 0.3 + rnd() * 0.8;
313	      while (a < len - 2) {
314	        const cl = 0.6 + rnd() * 1.0, n = Math.round(cl * (10 + rnd() * 8));
315	        for (let i = 0; i < n; i++) {
316	          const t = rnd(), rad = 0.05 + Math.pow(rnd(), 1.6) * 0.2 * (1 - Math.abs(t - 0.5));
317	          const up = rnd() * 0.5 * (1 - Math.abs(t - 0.5) * 1.4);
318	          const th = Math.asin(Math.min(1, waterHalf / r)) + up / r; // walk up the wall from the water line (th 0 = bottom)
319	          const x = side * (r * Math.sin(th) - 0.12 - rnd() * 0.4), y = cy - r * Math.cos(th) + rad * 0.5 + rnd() * 0.08;
320	          items.push({ p: new THREE.Vector3(cx + x, Math.max(rad * 0.5, y), z0 - a - t * cl), r: rad, s: rnd() });
321	        }
322	        a += cl + 0.4 + rnd() * 1.4;
323	      }
324	    }
325	    // before the opening: the painted foam banks left and right of the river (bigger clusters)
326	    for (let a = -7; a < 0; a += 0.3) for (const side of [-1, 1]) {
327	      const n = 3 + Math.floor(rnd() * 3);
328	      for (let i = 0; i < n; i++) {
329	        const rad = 0.14 + rnd() * 0.32;
330	        const x = cx + side * (waterHalf + 0.2 + rnd() * 2.2);
331	        items.push({ p: new THREE.Vector3(x, rad * 0.55 + rnd() * 0.3, z0 - a + rnd() * 0.3), r: rad, s: rnd() });
332	      }
333	    }
334	    sprites(items, FOAM_FRAG, 'm04_foam', 3);
335	  }
336	  if (M04.bub) {
337	    const items: { p: THREE.Vector3; r: number; s: number }[] = [];
